import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.OLpNgP4A.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"ai-ml/index.md","filePath":"ai-ml/index.md","lastUpdated":1789221836000}'),n={name:"ai-ml/index.md"};function i(s,e,l,c,d,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h2 id="ai-machine-learning-reading-list" tabindex="-1">AI &amp; Machine Learning Reading List <a class="header-anchor" href="#ai-machine-learning-reading-list" aria-label="Permalink to &quot;AI &amp; Machine Learning Reading List&quot;">​</a></h2><p>A structured collection of books covering core mathematical foundations, machine learning theory, deep learning architectures, and modern LLM engineering.</p><h3 id="_1-foundations-mathematics" tabindex="-1">1. Foundations &amp; Mathematics <a class="header-anchor" href="#_1-foundations-mathematics" aria-label="Permalink to &quot;1. Foundations &amp; Mathematics&quot;">​</a></h3><ul><li><strong>&quot;Mathematics for Machine Learning&quot;</strong> by Marc Peter Deisenroth, A. Faisal, and Cheng Soon Ong <ul><li><em>Focus:</em> The essential linear algebra, multivariate calculus, and probability theory needed to truly understand how ML algorithms work under the hood.</li></ul></li><li><strong>&quot;Python Data Science Handbook&quot;</strong> by Jake VanderPlas <ul><li><em>Focus:</em> Practical data manipulation, vectorization, and numerical computing using NumPy, Pandas, Scikit-Learn, and Matplotlib.</li></ul></li></ul><h3 id="_2-core-machine-learning" tabindex="-1">2. Core Machine Learning <a class="header-anchor" href="#_2-core-machine-learning" aria-label="Permalink to &quot;2. Core Machine Learning&quot;">​</a></h3><ul><li><strong>&quot;Hands-On Machine Learning with Scikit-Learn, Keras, and TensorFlow&quot;</strong> by Aurélien Géron <ul><li><em>Focus:</em> The gold standard practical guide for building end-to-end ML pipelines—from classic regression and classification models to deep neural networks.</li></ul></li><li><strong>&quot;The Elements of Statistical Learning&quot;</strong> by Trevor Hastie, Robert Tibshirani, and Jerome Friedman <ul><li><em>Focus:</em> The definitive theoretical textbook for understanding the statistical and analytical principles driving machine learning algorithms.</li></ul></li></ul><h3 id="_3-deep-learning-neural-networks" tabindex="-1">3. Deep Learning &amp; Neural Networks <a class="header-anchor" href="#_3-deep-learning-neural-networks" aria-label="Permalink to &quot;3. Deep Learning &amp; Neural Networks&quot;">​</a></h3><ul><li><strong>&quot;Deep Learning&quot;</strong> by Ian Goodfellow, Yoshua Bengio, and Aaron Courville <ul><li><em>Focus:</em> Comprehensive mathematical and theoretical framing of deep architectures, regularization, optimization, and sequence modeling.</li></ul></li></ul><h3 id="_4-modern-genai-llms-agents" tabindex="-1">4. Modern GenAI, LLMs, &amp; Agents <a class="header-anchor" href="#_4-modern-genai-llms-agents" aria-label="Permalink to &quot;4. Modern GenAI, LLMs, &amp; Agents&quot;">​</a></h3><ul><li><strong>&quot;Building LLMs for Production&quot;</strong> (or current applied engineering guides on Large Language Models &amp; Retrieval-Augmented Generation) <ul><li><em>Focus:</em> Practical architectures for fine-tuning, prompt engineering, vector databases, RAG pipelines, and deploying autonomous AI agents safely in production.</li></ul></li></ul><hr><h2 id="recommended-github-repositories-for-data-science" tabindex="-1">Recommended GitHub Repositories for Data Science <a class="header-anchor" href="#recommended-github-repositories-for-data-science" aria-label="Permalink to &quot;Recommended GitHub Repositories for Data Science&quot;">​</a></h2><p>GitHub repositories for data science. Organized into clear categories so you can easily navigate based on your needs whether you&#39;re a beginner, intermediate, or looking for projects/MLOps.</p><blockquote><p><strong>Note &amp; Action Item:</strong> Since I am currently juggling other concurrent projects, these repositories are organized here as a reference to implement step-by-step and tackle as a to-do list for future milestones.</p></blockquote><h2 id="_1-awesome-curated-lists-your-master-index" tabindex="-1">1. Awesome Curated Lists (Your &quot;Master Index&quot;) <a class="header-anchor" href="#_1-awesome-curated-lists-your-master-index" aria-label="Permalink to &quot;1. Awesome Curated Lists (Your &quot;Master Index&quot;)&quot;">​</a></h2><p>These are massive resource collections covering tools, courses, books, and more.</p><ul><li><strong><a href="https://github.com/academic/awesome-datascience" target="_blank" rel="noreferrer">academic/awesome-datascience</a></strong> — The #1 go-to curated list for data science. Covers everything from basics to real-world applications, books, courses, and tools.</li><li><strong><a href="https://github.com/josephmisiti/awesome-machine-learning" target="_blank" rel="noreferrer">josephmisiti/awesome-machine-learning</a></strong> — Comprehensive list focused on ML algorithms, libraries, and resources across languages.</li><li><strong><a href="https://github.com/vinta/awesome-python" target="_blank" rel="noreferrer">vinta/awesome-python</a></strong> — Best Python ecosystem list (includes data science, ML, and visualization libraries).</li><li><strong><a href="https://github.com/awesomedata/awesome-public-datasets" target="_blank" rel="noreferrer">awesomedata/awesome-public-datasets</a></strong> — Curated high-quality open datasets for practice and projects.</li><li><strong><a href="https://github.com/quantmind/awesome-data-science-viz" target="_blank" rel="noreferrer">quantmind/awesome-data-science-viz</a></strong> — Focused on data visualization, analysis, and Python/web tools.</li></ul><h2 id="_2-learning-roadmaps-structured-curricula" tabindex="-1">2. Learning Roadmaps &amp; Structured Curricula <a class="header-anchor" href="#_2-learning-roadmaps-structured-curricula" aria-label="Permalink to &quot;2. Learning Roadmaps &amp; Structured Curricula&quot;">​</a></h2><p>Perfect for self-paced learning with clear paths.</p><ul><li><strong><a href="https://github.com/microsoft/Data-Science-For-Beginners" target="_blank" rel="noreferrer">microsoft/Data-Science-For-Beginners</a></strong> — Free 10-week curriculum with 20 lessons, notebooks, and exercises (Microsoft-backed).</li><li><strong><a href="https://github.com/Avik-Jain/100-Days-Of-ML-Code" target="_blank" rel="noreferrer">Avik-Jain/100-Days-Of-ML-Code</a></strong> — Classic 100-day ML challenge with daily code and concepts.</li><li><strong><a href="https://github.com/CIS-Team/Data-Science-Roadmap-2025" target="_blank" rel="noreferrer">CIS-Team/Data-Science-Roadmap-2025</a></strong> — Complete A-to-Z roadmap (statistics → Python → ML → projects).</li><li><strong><a href="https://github.com/krishnaik06/Perfect-Roadmap-To-Learn-Data-Science-In-2025" target="_blank" rel="noreferrer">krishnaik06/Perfect-Roadmap-To-Learn-Data-Science-In-2025</a></strong> — Practical end-to-end roadmap with projects (includes NLP, MLOps, and deployment).</li><li><strong><a href="https://github.com/mhmdkardosha/CAT-Reloaded-2025-Data-Science-Roadmap" target="_blank" rel="noreferrer">mhmdkardosha/CAT-Reloaded-2025-Data-Science-Roadmap</a></strong> — Week-by-week structured tasks for beginners to advanced.</li></ul><h2 id="_3-core-libraries-must-know-foundations" tabindex="-1">3. Core Libraries (Must-Know Foundations) <a class="header-anchor" href="#_3-core-libraries-must-know-foundations" aria-label="Permalink to &quot;3. Core Libraries (Must-Know Foundations)&quot;">​</a></h2><p>Daily tools every data scientist uses.</p><ul><li><strong><a href="https://github.com/pandas-dev/pandas" target="_blank" rel="noreferrer">pandas-dev/pandas</a></strong> — The essential library for data manipulation and analysis.</li><li><strong><a href="https://github.com/scikit-learn/scikit-learn" target="_blank" rel="noreferrer">scikit-learn/scikit-learn</a></strong> — Classical ML (classification, regression, clustering, preprocessing).</li><li><strong><a href="https://github.com/numpy/numpy" target="_blank" rel="noreferrer">numpy/numpy</a></strong> — Numerical computing foundation (works hand-in-hand with pandas).</li><li><strong><a href="https://github.com/matplotlib/matplotlib" target="_blank" rel="noreferrer">matplotlib/matplotlib</a></strong> + <strong><a href="https://github.com/mwaskom/seaborn" target="_blank" rel="noreferrer">seaborn/seaborn</a></strong> — Core visualization libraries.</li></ul><h2 id="_4-machine-learning-deep-learning-frameworks" tabindex="-1">4. Machine Learning &amp; Deep Learning Frameworks <a class="header-anchor" href="#_4-machine-learning-deep-learning-frameworks" aria-label="Permalink to &quot;4. Machine Learning &amp; Deep Learning Frameworks&quot;">​</a></h2><p>For building models.</p><ul><li><strong><a href="https://github.com/pytorch/pytorch" target="_blank" rel="noreferrer">pytorch/pytorch</a></strong> — Most popular for research and flexibility.</li><li><strong><a href="https://github.com/tensorflow/tensorflow" target="_blank" rel="noreferrer">tensorflow/tensorflow</a></strong> — End-to-end production-ready deep learning (Google-backed).</li><li><strong><a href="https://github.com/keras-team/keras" target="_blank" rel="noreferrer">keras-team/keras</a></strong> — High-level API for quick neural network prototyping (runs on TensorFlow).</li><li><strong><a href="https://github.com/huggingface/transformers" target="_blank" rel="noreferrer">huggingface/transformers</a></strong> — State-of-the-art NLP, LLMs, and multimodal models.</li><li><strong><a href="https://github.com/dmlc/xgboost" target="_blank" rel="noreferrer">dmlc/xgboost</a></strong> and <strong><a href="https://github.com/microsoft/LightGBM" target="_blank" rel="noreferrer">microsoft/LightGBM</a></strong> — Gradient boosting powerhouses for tabular data competitions.</li></ul><h2 id="_5-hands-on-projects-portfolio-builders" tabindex="-1">5. Hands-On Projects &amp; Portfolio Builders <a class="header-anchor" href="#_5-hands-on-projects-portfolio-builders" aria-label="Permalink to &quot;5. Hands-On Projects &amp; Portfolio Builders&quot;">​</a></h2><p>Build real projects to strengthen your GitHub profile.</p><ul><li><strong><a href="https://github.com/durgeshsamariya/Data-Science-Machine-Learning-Project-with-Source-Code" target="_blank" rel="noreferrer">durgeshsamariya/Data-Science-Machine-Learning-Project-with-Source-Code</a></strong> — Huge collection of projects with code and explanations.</li><li><strong><a href="https://github.com/veb-101/Data-Science-Projects" target="_blank" rel="noreferrer">veb-101/Data-Science-Projects</a></strong> — Curated list of project ideas with resources across industries.</li><li><strong><a href="https://github.com/rhiever/Data-Analysis-and-Machine-Learning-Projects" target="_blank" rel="noreferrer">rhiever/Data-Analysis-and-Machine-Learning-Projects</a></strong> — Teaching-focused projects with datasets and code.</li></ul><h2 id="_6-bonus-mlops-production-specialized" tabindex="-1">6. Bonus: MLOps, Production &amp; Specialized <a class="header-anchor" href="#_6-bonus-mlops-production-specialized" aria-label="Permalink to &quot;6. Bonus: MLOps, Production &amp; Specialized&quot;">​</a></h2><ul><li><strong><a href="https://github.com/DataTalksClub/machine-learning-zoomcamp" target="_blank" rel="noreferrer">DataTalksClub/machine-learning-zoomcamp</a></strong> (and <strong><a href="https://github.com/DataTalksClub/mlops-zoomcamp" target="_blank" rel="noreferrer">DataTalksClub/mlops-zoomcamp</a></strong>) — Free project-based courses on ML engineering and production.</li></ul><h2 id="quick-start-advice" tabindex="-1">Quick Start Advice <a class="header-anchor" href="#quick-start-advice" aria-label="Permalink to &quot;Quick Start Advice&quot;">​</a></h2><ul><li><strong>Beginner</strong>: Start with <strong>awesome-datascience</strong> + <strong>Data-Science-For-Beginners</strong> + <strong>pandas</strong> + <strong>100-Days-Of-ML-Code</strong>.</li><li><strong>Intermediate/Advanced</strong>: Dive into <strong>PyTorch</strong> or <strong>Transformers</strong> + build 5–10 projects from the project repos.</li><li><strong>Pro Tip</strong>: Star these repos, fork interesting ones, and contribute small improvements — it’s great for learning and your resume.</li></ul>',33)])])}const m=a(n,[["render",i]]);export{h as __pageData,m as default};
